import { submitBattleResult, type SubmitBattleResultResponse } from '../utils/battleLeaderboard';
import { getBattleTier, getTierIndex } from '../utils/battleTier';
import BaseScene from './BaseScene';

interface BattleResultData {
  result: BattleResult;
  roomCode: string;
  opponentId?: string;
}

/**
 * 대전 결과 씬
 * - 승리/패배/연결끊김 표시
 * - 양쪽 점수 비교
