      fontSize: '15px',
      color: '#aaaaaa',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5);

    this.rpDeltaText = this.add.text(200, 155, '', {
      fontSize: '18px',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 4,
    }).setOrigin(0.5);

    this.currentRpText = this.add.text(200, 185, '', {
      fontSize: '13px',
      color: '#888888',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5);

    // 재대전 버튼
    const rematchBtn = this.add.rectangle(200, 310, 250, 50, 0xe74c3c);
    rematchBtn.setStrokeStyle(3, 0xffffff);
